import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { exit, snap, spring } from "../lib/motion";
import { useControllableState } from "../lib/use-controllable-state";
import { cn } from "../lib/utils";
import { Button } from "./button";
import { Dialog, DialogContent, DialogDescription, DialogTitle, DialogTrigger } from "./dialog";
import { Icon } from "./icon";
import { ProgressSteps } from "./progress";
import { Sheet, SheetContent, SheetDescription, SheetTitle, SheetTrigger } from "./sheet";

import styles from "./multi-step.module.css";

type ValidateResult = boolean | string | void;

export interface MultiStepStep {
  title: string;
  heading?: string;
  description?: React.ReactNode;
  summary?: React.ReactNode;
  content: React.ReactNode;
  validate?: () => ValidateResult | Promise<ValidateResult>;
  nextLabel?: string;
}

export type StepsProps = {
  steps: readonly Pick<MultiStepStep, "title" | "summary">[];
  current: number;
  label?: string;
} & (
  | { orientation?: "horizontal"; onStepClick?: never }
  | { orientation: "vertical"; onStepClick?: (index: number) => void }
);

export const Steps = ({
  steps,
  current,
  orientation = "horizontal",
  onStepClick,
  label = "Steps"
}: StepsProps) => {
  if (orientation === "horizontal")
    return (
      <ProgressSteps steps={steps.map((entry) => entry.title)} current={current} label={label} />
    );
  return (
    <ol data-slot="steps" aria-label={label} className={styles.steps}>
      {steps.map((entry, index) => {
        const state = index < current ? "done" : index === current ? "current" : "upcoming";
        const marker = (
          <>
            <span className={styles.marker} aria-hidden="true">
              {state === "done" ? <Icon name="check" size={14} /> : index + 1}
            </span>
            <span className={styles.stepText}>
              <span className={styles.stepTitle}>{entry.title}</span>
              {entry.summary && <span className={styles.stepSummary}>{entry.summary}</span>}
            </span>
          </>
        );
        return (
          <li
            key={entry.title}
            className={styles.step}
            data-state={state}
            aria-current={state === "current" ? "step" : undefined}
          >
            {onStepClick && index < current ? (
              <button
                type="button"
                className={styles.stepButton}
                onClick={() => onStepClick(index)}
              >
                {marker}
              </button>
            ) : (
              <span className={styles.stepButton}>{marker}</span>
            )}
          </li>
        );
      })}
    </ol>
  );
};

export type MultiStepProps = {
  steps: readonly MultiStepStep[];
  variant?: "dialog" | "sheet" | "page";
  title?: React.ReactNode;
  description?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  trigger?: React.ReactElement;
  onComplete?: () => void | Promise<unknown>;
  completeLabel?: string;
  onCancel?: () => void;
  step?: number;
  defaultStep?: number;
  onStepChange?: (step: number) => void;
  className?: string;
};

const fieldSelector =
  ":is(input:not([type=hidden]), textarea, select, [role=combobox], button[role=radio], button[role=checkbox], button[role=switch]):not(:disabled, [aria-disabled=true])";

export const MultiStep = ({
  steps,
  variant = "dialog",
  title,
  description,
  open,
  defaultOpen = false,
  onOpenChange,
  trigger,
  onComplete,
  completeLabel = "Finish",
  onCancel,
  step,
  defaultStep = 0,
  onStepChange,
  className
}: MultiStepProps) => {
  const [isOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange
  });
  const [current, setCurrent] = useControllableState({
    value: step,
    defaultValue: defaultStep,
    onChange: onStepChange
  });
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState<string>();
  const [direction, setDirection] = React.useState(1);
  const viewport = React.useRef<HTMLDivElement | null>(null);
  const activeStep = () =>
    viewport.current?.querySelector<HTMLElement>(`[data-step="${current}"]`) ?? null;
  const moved = React.useRef(false);
  const reduced = useReducedMotion();
  const entry = steps[current];
  const last = current === steps.length - 1;
  React.useEffect(() => {
    if (!moved.current) return;
    moved.current = false;
    viewport.current
      ?.querySelector<HTMLElement>(`[data-step="${current}"]`)
      ?.querySelector<HTMLElement>(fieldSelector)
      ?.focus();
  }, [current]);
  const move = (target: number) => {
    setError(undefined);
    setDirection(target > current ? 1 : -1);
    moved.current = true;
    setCurrent(target);
  };
  const reset = () => {
    setError(undefined);
    if (current !== defaultStep) setCurrent(defaultStep);
  };
  const changeOpen = (next: boolean) => {
    if (!next) {
      if (busy) return;
      onCancel?.();
      reset();
    }
    setOpen(next);
  };
  const refocus = React.useRef(false);
  React.useEffect(() => {
    if (busy || !refocus.current) return;
    refocus.current = false;
    activeStep()?.querySelector<HTMLElement>("[aria-invalid=true]")?.focus();
  });
  const advance = async () => {
    if (busy || !entry) return;
    setError(undefined);
    setBusy(true);
    try {
      const result = await entry.validate?.();
      if (result === false) {
        refocus.current = true;
        return;
      }
      if (typeof result === "string") {
        setError(result);
        return;
      }
      if (!last) {
        move(current + 1);
        return;
      }
      await onComplete?.();
      if (variant !== "page") {
        reset();
        setOpen(false);
      }
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : "Something went wrong. Try again.");
    } finally {
      setBusy(false);
    }
  };
  if (!entry) return null;
  const travel = reduced ? 0 : 24;
  const stepHead = (
    <div className={styles.stepHead}>
      {variant === "page" && (
        <p className={styles.eyebrow}>
          Step {current + 1} of {steps.length}
        </p>
      )}
      <h3 className={styles.heading}>{entry.heading ?? entry.title}</h3>
      {entry.description && <p className={styles.lede}>{entry.description}</p>}
    </div>
  );
  const flow = (
    <form
      noValidate
      className={styles.form}
      onSubmit={(event) => {
        event.preventDefault();
        advance();
      }}
    >
      <fieldset disabled={busy} className={styles.fields}>
        <motion.div
          ref={viewport}
          layout={!reduced}
          transition={spring.moderate}
          className={styles.viewport}
        >
          <AnimatePresence mode="popLayout" initial={false} custom={direction}>
            <motion.div
              key={current}
              data-step={current}
              className={styles.body}
              initial={{ opacity: 0, x: direction * travel }}
              animate={{ opacity: 1, x: 0, transition: reduced ? snap : spring.moderate }}
              exit={{
                opacity: 0,
                x: -direction * travel,
                transition: reduced ? snap : exit.moderate
              }}
            >
              {stepHead}
              {entry.content}
            </motion.div>
          </AnimatePresence>
        </motion.div>
      </fieldset>
      <div className={styles.footer}>
        <p className={cn(styles.status, error && styles.error)} role="status">
          {error ?? (variant === "page" ? null : `Step ${current + 1} of ${steps.length}`)}
        </p>
        <div className={styles.buttons}>
          {current === 0 ? (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => changeOpen(false)}
              disabled={busy}
            >
              Cancel
            </Button>
          ) : (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => move(current - 1)}
              disabled={busy}
            >
              Back
            </Button>
          )}
          <Button type="submit" variant="primary" size="sm" loading={busy}>
            {last ? completeLabel : (entry.nextLabel ?? "Continue")}
          </Button>
        </div>
      </div>
    </form>
  );
  const indicator = (
    <Steps
      steps={steps}
      current={current}
      label={typeof title === "string" ? `${title} steps` : "Steps"}
    />
  );
  if (variant === "page")
    return (
      <div data-slot="multi-step" data-variant="page" className={cn(styles.page, className)}>
        <div className={styles.pageGrid}>
          <div className={styles.rail}>
            <Steps
              steps={steps}
              current={current}
              orientation="vertical"
              onStepClick={busy ? undefined : move}
            />
          </div>
          <div className={styles.bar}>{indicator}</div>
          <div className={styles.card}>{flow}</div>
        </div>
      </div>
    );
  const content = (
    <div data-slot="multi-step" data-variant={variant} className={cn(styles.panel, className)}>
      <div className={styles.header}>
        {variant === "dialog" ? (
          <DialogTitle className={styles.title}>{title}</DialogTitle>
        ) : (
          <SheetTitle className={styles.title}>{title}</SheetTitle>
        )}
        {description &&
          (variant === "dialog" ? (
            <DialogDescription className={styles.lede}>{description}</DialogDescription>
          ) : (
            <SheetDescription className={styles.lede}>{description}</SheetDescription>
          ))}
        {indicator}
      </div>
      {flow}
    </div>
  );
  if (variant === "sheet")
    return (
      <Sheet open={isOpen} onOpenChange={changeOpen}>
        {trigger && <SheetTrigger asChild>{trigger}</SheetTrigger>}
        <SheetContent className={styles.sheet}>{content}</SheetContent>
      </Sheet>
    );
  return (
    <Dialog open={isOpen} onOpenChange={changeOpen}>
      {trigger && <DialogTrigger asChild>{trigger}</DialogTrigger>}
      <DialogContent className={styles.dialog}>{content}</DialogContent>
    </Dialog>
  );
};

.panel {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-20);
  min-width: 0;
  height: 100%;
}
.dialog.dialog {
  display: block;
}
.sheet.sheet {
  padding: var(--v4-space-overlay-inset);
}
.header {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-12);
  padding-inline-end: var(--v4-space-32);
}
.title {
  margin: 0;
  font-family: var(--v4-type-title-font-family);
  font-size: var(--v4-type-title-font-size);
  line-height: var(--v4-type-title-line-height);
  font-weight: var(--v4-type-title-font-weight);
  letter-spacing: var(--v4-type-title-letter-spacing);
}
.lede {
  margin: 0;
  color: var(--v4-text2);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
}
.form {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--v4-space-20);
  min-width: 0;
}
.viewport {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
}
.body {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-field-group);
  min-width: 0;
  padding: var(--v4-space-2);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-12);
}
.status {
  min-width: 0;
  margin: 0;
  color: var(--v4-muted);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
}
.error {
  color: var(--v4-bad);
}
.buttons {
  display: flex;
  flex: none;
  gap: var(--v4-space-12);
  margin-inline-start: auto;
}
.page {
  container-type: inline-size;
  min-width: 0;
}
.pageGrid {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: var(--v4-space-32);
  align-items: start;
  min-width: 0;
}
.bar {
  display: none;
}
.card {
  min-width: 0;
  padding: var(--v4-space-surface-inset);
  border: var(--v4-size-control-border) solid var(--v4-line);
  border-radius: calc(var(--v4-radius-card) * var(--corners));
  background: var(--v4-surface);
}
@container (max-width: 640px) {
  .pageGrid {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--v4-space-16);
  }
  .rail {
    display: none;
  }
  .bar {
    display: block;
  }
}
.stepHead {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-4);
  margin-bottom: var(--v4-space-8);
}
.eyebrow {
  margin: 0;
  color: var(--v4-muted);
  font-family: var(--v4-type-eyebrow-font-family);
  font-size: var(--v4-type-eyebrow-font-size);
  line-height: var(--v4-type-eyebrow-line-height);
  font-weight: var(--v4-type-eyebrow-font-weight);
  letter-spacing: var(--v4-type-eyebrow-letter-spacing);
  text-transform: uppercase;
}
.heading {
  margin: 0;
  font-family: var(--v4-type-title-font-family);
  font-size: var(--v4-type-title-font-size);
  line-height: var(--v4-type-title-line-height);
  font-weight: var(--v4-type-title-font-weight);
  letter-spacing: var(--v4-type-title-letter-spacing);
}
.steps {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}
.step {
  position: relative;
  padding-bottom: var(--v4-space-20);
}
.step:not(:last-child)::before {
  content: "";
  position: absolute;
  top: var(--v4-space-24);
  bottom: 0;
  left: 11px;
  width: 1px;
  background: var(--v4-line);
}
.step[data-state="done"]::before {
  background: var(--v4-ink);
}
.stepButton {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: start;
}
button.stepButton {
  cursor: pointer;
}
button.stepButton:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: var(--v4-size-focus-ring);
}
.marker {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--v4-space-24);
  height: var(--v4-space-24);
  border: 1px solid var(--v4-line);
  border-radius: calc(var(--v4-radius-xs) * var(--corners));
  background: var(--v4-surface);
  color: var(--v4-muted);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  font-variant-numeric: tabular-nums;
}
.step[data-state="current"] .marker {
  border-color: var(--v4-ink);
  color: var(--v4-ink);
}
.step[data-state="done"] .marker {
  border-color: var(--v4-ink);
  background: var(--v4-ink);
  color: var(--v4-on-ink);
}
.stepText {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding-top: 2px;
}
.stepTitle {
  color: var(--v4-text2);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
}
.step[data-state="current"] .stepTitle {
  color: var(--v4-ink);
  font-weight: 600;
}
.stepSummary {
  overflow: hidden;
  color: var(--v4-muted);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fields {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
